// Draws Sunflower Days' procedural art: layered sprites for Hana and Ren,
// three backgrounds, two event pictures (CGs), and two rule-wipe masks.
// Simple shapes only: placeholders are procedural, never generated by AI
// (plan §1.5). Run from this folder: node make-art.mjs
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { deflateSync } from "node:zlib";

function crc32(buf) {
  let c = ~0;
  for (const b of buf) {
    c ^= b;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  }
  return ~c >>> 0;
}

function png(W, H, rgba) {
  const raw = Buffer.alloc((W * 4 + 1) * H);
  for (let y = 0; y < H; y++) rgba.copy(raw, y * (W * 4 + 1) + 1, y * W * 4, (y + 1) * W * 4);
  const chunk = (type, data) => {
    const len = Buffer.alloc(4);
    len.writeUInt32BE(data.length);
    const td = Buffer.concat([Buffer.from(type), data]);
    const crc = Buffer.alloc(4);
    crc.writeUInt32BE(crc32(td));
    return Buffer.concat([len, td, crc]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(W, 0);
  ihdr.writeUInt32BE(H, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", deflateSync(raw, { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}

/** A canvas with shape helpers; returns PNG bytes. */
function canvas(W, H, draw) {
  const px = Buffer.alloc(W * H * 4);
  const put = (x, y, [r, g, b, a = 255]) => {
    if (x < 0 || y < 0 || x >= W || y >= H) return;
    const i = (y * W + x) * 4;
    px[i] = r;
    px[i + 1] = g;
    px[i + 2] = b;
    px[i + 3] = a;
  };
  const ellipse = (cx, cy, rx, ry, color) => {
    for (let y = Math.max(0, Math.floor(cy - ry)); y <= Math.min(H - 1, cy + ry); y++)
      for (let x = Math.max(0, Math.floor(cx - rx)); x <= Math.min(W - 1, cx + rx); x++)
        if (((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2 <= 1) put(x, y, color);
  };
  const rect = (x0, y0, x1, y1, color) => {
    for (let y = Math.max(0, y0); y < Math.min(H, y1); y++) for (let x = Math.max(0, x0); x < Math.min(W, x1); x++) put(x, y, color);
  };
  const gradient = (top, bottom, y0 = 0, y1 = H) => {
    for (let y = y0; y < y1; y++) {
      const t = (y - y0) / Math.max(1, y1 - y0 - 1);
      const c = top.map((v, i) => Math.round(v + (bottom[i] - v) * t));
      for (let x = 0; x < W; x++) put(x, y, c);
    }
  };
  const each = (fn) => {
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) put(x, y, fn(x, y));
  };
  draw({ ellipse, rect, gradient, each, W, H });
  return png(W, H, px);
}

const out = (path, bytes) => {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, bytes);
};

// ---- characters: 400 × 900 layers (plan §6.2: assets/sprites/<id>/<group>/<attr>.png) ----

function character(id, look) {
  const S = (draw) => canvas(400, 900, draw);
  const layers = {
    "body/base": ({ ellipse, rect }) => {
      rect(170, 300, 230, 360, look.skin);
      ellipse(200, 210, 110, 125, look.skin);
      ellipse(200, look.hairY, 125, look.hairH, look.hair);
      rect(110, 350, 290, 900, look.skin);
    },
    "eyes/neutral": ({ ellipse }) => {
      ellipse(160, 215, 14, 20, look.ink);
      ellipse(240, 215, 14, 20, look.ink);
    },
    "eyes/neutral_half": ({ rect }) => {
      rect(146, 212, 174, 222, look.ink);
      rect(226, 212, 254, 222, look.ink);
    },
    "eyes/neutral_closed": ({ rect }) => {
      rect(146, 216, 174, 220, look.ink);
      rect(226, 216, 254, 220, look.ink);
    },
    "eyes/smile": ({ ellipse }) => {
      ellipse(160, 218, 16, 8, look.ink);
      ellipse(240, 218, 16, 8, look.ink);
      ellipse(160, 224, 16, 8, look.skin);
      ellipse(240, 224, 16, 8, look.skin);
    },
    "eyes/wide": ({ ellipse }) => {
      ellipse(160, 212, 18, 26, look.ink);
      ellipse(240, 212, 18, 26, look.ink);
      ellipse(165, 204, 6, 7, [255, 255, 255]);
      ellipse(245, 204, 6, 7, [255, 255, 255]);
    },
    "mouth/neutral": ({ rect }) => rect(180, 275, 220, 281, look.ink),
    "mouth/neutral_open": ({ ellipse }) => ellipse(200, 279, 14, 10, look.ink),
    "mouth/smile": ({ ellipse }) => {
      ellipse(200, 272, 26, 16, look.ink);
      ellipse(200, 264, 28, 14, look.skin);
    },
    "mouth/smile_open": ({ ellipse }) => {
      ellipse(200, 276, 24, 16, look.ink);
      ellipse(200, 268, 26, 10, look.skin);
    },
    "mouth/o": ({ ellipse }) => ellipse(200, 280, 10, 14, look.ink),
    ...look.outfits,
  };
  for (const [name, draw] of Object.entries(layers)) out(`assets/sprites/${id}/${name}.png`, S(draw));
}

character("hana", {
  skin: [250, 222, 200],
  hair: [70, 45, 35],
  hairY: 125,
  hairH: 95,
  ink: [60, 40, 50],
  outfits: {
    "outfit/summer": ({ rect }) => {
      rect(100, 360, 300, 900, [250, 250, 245]);
      rect(100, 360, 300, 380, [245, 190, 40]);
    },
    "outfit/yukata": ({ rect }) => {
      rect(100, 360, 300, 900, [60, 80, 170]);
      for (let y = 420; y < 900; y += 90) rect(120, y, 160, y + 40, [245, 190, 40]);
      rect(100, 560, 300, 610, [230, 120, 60]); // obi
    },
    "hair/sunflower_pin": ({ ellipse }) => {
      ellipse(285, 110, 26, 26, [245, 190, 40]);
      ellipse(285, 110, 11, 11, [110, 70, 30]);
    },
    "hair/ribbon": ({ rect }) => rect(110, 100, 150, 130, [230, 70, 100]),
  },
});

character("ren", {
  skin: [240, 210, 185],
  hair: [30, 30, 40],
  hairY: 115,
  hairH: 80,
  ink: [35, 35, 45],
  outfits: {
    "outfit/uniform": ({ rect }) => {
      rect(100, 360, 300, 900, [35, 45, 70]);
      rect(190, 360, 210, 520, [250, 250, 250]);
    },
    "outfit/jinbei": ({ rect }) => rect(100, 360, 300, 900, [120, 140, 110]),
    "hair/glasses": ({ rect }) => {
      rect(138, 200, 182, 204, [20, 20, 20]);
      rect(218, 200, 262, 204, [20, 20, 20]);
      rect(182, 206, 218, 209, [20, 20, 20]);
    },
  },
});

// ---- backgrounds and CGs: 1920 × 1080 ----

const sunflower = (ellipse, x, y, r) => {
  for (let k = 0; k < 12; k++) {
    const a = (k / 12) * Math.PI * 2;
    ellipse(x + Math.cos(a) * r, y + Math.sin(a) * r, r * 0.55, r * 0.55, [245, 190, 40]);
  }
  ellipse(x, y, r * 0.75, r * 0.75, [110, 70, 30]);
};

out("assets/bg/sunflower_field.png", canvas(1920, 1080, ({ gradient, ellipse, rect }) => {
  gradient([110, 180, 240], [200, 230, 250], 0, 640);
  gradient([90, 150, 60], [50, 100, 40], 640, 1080);
  ellipse(1600, 160, 90, 90, [255, 245, 200]);
  for (let i = 0; i < 26; i++) {
    const x = 60 + i * 73, y = 700 + (i % 3) * 90;
    rect(x - 4, y, x + 4, 1080, [60, 110, 40]);
    sunflower(ellipse, x, y, 26 + (i % 3) * 6);
  }
}));

out("assets/bg/classroom.png", canvas(1920, 1080, ({ gradient, rect }) => {
  gradient([235, 225, 205], [215, 200, 180], 0, 760);
  gradient([170, 130, 90], [140, 100, 70], 760, 1080);
  for (let i = 0; i < 3; i++) {
    rect(240 + i * 520, 140, 600 + i * 520, 560, [150, 200, 240]);
    rect(240 + i * 520, 340, 600 + i * 520, 352, [240, 240, 235]);
  }
  for (let i = 0; i < 4; i++) rect(180 + i * 430, 820, 480 + i * 430, 860, [120, 85, 55]);
}));

out("assets/bg/river_night.png", canvas(1920, 1080, ({ gradient, ellipse, rect }) => {
  gradient([15, 20, 55], [40, 50, 100], 0, 620);
  gradient([30, 40, 80], [10, 15, 35], 620, 1080);
  for (let i = 0; i < 60; i++) ellipse((i * 331) % 1920, (i * 97) % 560, 2, 2, [255, 255, 230]);
  for (let i = 0; i < 18; i++) {
    const x = 80 + i * 105, y = 700 + (i % 4) * 40;
    ellipse(x, y, 16, 22, [255, 170, 80]);
    rect(x - 2, y + 22, x + 2, y + 40, [60, 40, 30]);
  }
}));

out("assets/cg/fireworks.png", canvas(1920, 1080, ({ gradient, ellipse }) => {
  gradient([10, 10, 40], [30, 20, 70]);
  const bursts = [[480, 300, [255, 120, 120]], [1100, 220, [120, 200, 255]], [1500, 420, [255, 220, 100]], [800, 520, [180, 255, 160]]];
  for (const [cx, cy, c] of bursts) {
    for (let k = 0; k < 24; k++) {
      const a = (k / 24) * Math.PI * 2;
      for (let r = 30; r < 170; r += 28) ellipse(cx + Math.cos(a) * r, cy + Math.sin(a) * r, 6, 6, c);
    }
  }
}));

out("assets/cg/sunflower_sea.png", canvas(1920, 1080, ({ gradient, ellipse }) => {
  gradient([250, 200, 120], [250, 150, 90], 0, 500);
  gradient([70, 120, 50], [40, 80, 30], 500, 1080);
  for (let row = 0; row < 5; row++)
    for (let i = 0; i < 14; i++) sunflower(ellipse, 70 + i * 140 + (row % 2) * 70, 560 + row * 120, 34 + row * 8);
}));

// ---- rule-wipe masks (grayscale: dark pixels change first) ----

out("assets/rules/iris.png", canvas(512, 288, ({ each }) => each((x, y) => {
  const d = Math.min(1, Math.hypot(x - 256, (y - 144) * 1.78) / 293);
  const v = Math.round(d * 255);
  return [v, v, v];
})));

out("assets/rules/blinds.png", canvas(512, 288, ({ each }) => each((x, y) => {
  const v = Math.round(((y % 32) / 31) * 200 + (x / 511) * 55);
  return [v, v, v];
})));

console.log("Sunflower Days art written to assets/");
